mapper.select:
select * from ( select a.*,b.machine_name from t_xwyy_loss_setting a left join T_XWYY_MACHINE_INFO b on a.machine_id = b.id and b.del_flag = '0' where a.del_flag = '0'
and INSTR(big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0 and a.machine_id = #{machineId}
order by a.CREATE_TIME desc
) t
order by ${orderStr}

select count(1)
from t_xwyy_loss_setting
where del_flag = '0'
and big_roll_code = #{bigRollCode}
and big_roll_code is null
and machine_id = #{machineId}
and machine_id is null
and id != #{id}

mapper.update:
update t_xwyy_loss_setting
big_roll_code = #{bigRollCode}, machine_id = #{machineId,jdbcType=VARCHAR}, loss_rate = #{lossRate}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.delete:
update t_xwyy_loss_setting
set del_flag='1'
where id = #{id}
